buy_code:
if (
    {entry_start} <= 시분초 <= {entry_end}
    and 시가총액 <= {cap_max}
    and {rate_min} <= 등락율 <= {rate_max}
    and 당일거래대금 >= {day_money_min}
    and 현재가 > 최고현재가({breakout_window}, 1) * {breakout_mult}
    and 당일거래대금 >= 시가총액 * {cap_money_mult}
    and 전일동시간비 >= {prev_ratio_min}
    and 등락율각도({angle_window}, 1) >= {angle_min}
):
    self.Buy()

sell_code:
if 수익률 >= {take_hard}:
    self.Sell()
elif 수익률 <= -{stop_hard}:
    self.Sell()
elif 보유시간 >= {max_hold_sec}:
    self.Sell()
elif 수익률 >= {be_trigger} and 수익률 <= {be_floor}:
    self.Sell()
elif 최고수익률 >= {trail_trigger} and 수익률 <= 최고수익률 - {trail_gap}:
    self.Sell()
